window.__CG_SEARCH__=[{"title": "Cellular Gateway", "page": "Home", "url": "", "lvl": 1, "text": "Open-source gateway that connects your applications to real Android phones. Send and receive SMS and place calls through a REST API and signed webhooks."}, {"title": "Android app", "page": "Devices", "url": "docs/android.html", "lvl": 1, "text": "Build and install the gateway app, connect it to your server, and keep it reliable on real phones. Build and install # Open the android/ project in Android Studio (JDK 17), or build from the command line: bash Copy cd android ./gradlew assembleDebug adb install -r app/build/outputs/apk/debug/app-debug.apk The app targets Android 8.0 (API 26) and newer, and is currently version 0.3.0. The release build type has no signing configuration, so assembleRelease produces an unsigned APK until you add y"}, {"title": "Build and install", "page": "Android app", "url": "docs/android.html#build-and-install", "lvl": 2, "text": "Open the android/ project in Android Studio (JDK 17), or build from the command line: bash Copy cd android ./gradlew assembleDebug adb install -r app/build/outputs/apk/debug/app-debug.apk The app targets Android 8.0 (API 26) and newer, and is currently version 0.3.0. The release build type has no signing configuration, so assembleRelease produces an unsigned APK until you add your own signing setu"}, {"title": "Connect", "page": "Android app", "url": "docs/android.html#connect", "lvl": 2, "text": "Create a device in the dashboard. The one-time credentials appear as a QR code. Open the app and either scan the QR code or enter the server URL, device key and device token. Allow permissions for SMS and phone when prompted. Tap Connect. The device should show ONLINE in the dashboard. The app runs a foreground service. It registers over REST, opens the WebSocket, sends a heartbeat every 10 second"}, {"title": "HTTP and HTTPS", "page": "Android app", "url": "docs/android.html#http-and-https", "lvl": 2, "text": "Build Plain http:// Use for Debug Allowed Emulator ( http://10.0.2.2:8000 reaches the host machine) and local networks Release Blocked Production. The server URL must be https://"}, {"title": "Permissions", "page": "Android app", "url": "docs/android.html#permissions", "lvl": 2, "text": "Permission Why Internet, network state Connect to the server Camera Scan the QR code Send, receive and read SMS Send commands and report inbound messages Call phone, read phone state, answer phone calls Place calls, follow call state, and hang up Foreground service, boot completed, notifications Stay connected and restart after reboot"}, {"title": "Keeping phones reliable", "page": "Android app", "url": "docs/android.html#keeping-phones-reliable", "lvl": 2, "text": "Sideload the APK. Google Play restricts the SMS and call permissions to default SMS and dialer apps. Disable battery optimization for the app, and allow autostart and background activity on manufacturers that restrict it. Use a SIM plan that suits your expected volume. Android may throttle or prompt on bursts of outgoing SMS. Keep the phone charged and on a stable connection. The gateway marks a p"}, {"title": "API reference", "page": "Integrate", "url": "docs/api.html", "lvl": 1, "text": "Authentication, messages, calls, commands, devices, groups, users and API keys, with request and response examples. All endpoints live under /api/v1 and speak JSON. In development, /docs serves the full interactive OpenAPI schema; it is disabled in production. Authentication # Method How Accepted on API key X-API-Key: cgk_... . Created by an administrator in the dashboard and shown once /messages , /calls and /commands endpoints only Bearer token Authorization: Bearer <jwt> from POST /auth/login All user endpoi"}, {"title": "Authentication", "page": "API reference", "url": "docs/api.html#authentication", "lvl": 2, "text": "Method How Accepted on API key X-API-Key: cgk_... . Created by an administrator in the dashboard and shown once /messages , /calls and /commands endpoints only Bearer token Authorization: Bearer <jwt> from POST /auth/login All user endpoints Session cookie cg_session , httpOnly and SameSite=Strict ( Secure in production), set by the same login call. Used by the dashboard. Writes also require an al"}, {"title": "Errors", "page": "API reference", "url": "docs/api.html#errors", "lvl": 2, "text": "Errors return a JSON body with a detail message. Status Meaning Example detail 400 Rejected input, such as a webhook URL that resolves to a private address Target resolves to a non-public address (10.0.0.5) 401 Missing or invalid credentials Not authenticated , Invalid API key 403 Role too low, or cookie request from a disallowed origin Insufficient permissions 404 Unknown resource Device group no"}, {"title": "Messages", "page": "API reference", "url": "docs/api.html#messages", "lvl": 2, "text": "POST /api/v1/messages Creates an outbound SMS. Requires the operator or admin role. Field Type Description to string Destination number. Required message string 1 to 1600 characters. Required device string Device key or UUID. Targets one phone group string Group slug or UUID. A phone is chosen by strategy strategy string healthiest (default), round_robin , highest_battery , least_load queue boolea"}, {"title": "Calls", "page": "API reference", "url": "docs/api.html#calls", "lvl": 2, "text": "POST /api/v1/calls Starts an outbound call. Fields: to (required), device , group , strategy , queue . Calls have no failover. Requires the operator or admin role. Response, 201 Created (queued) Copy { \"id\": \"fbb03c0c-8400-4fbf-86a1-df007623e879\", \"device_id\": \"ddb526df-d092-4bf1-a45d-5a176eaaf705\", \"request_id\": \"req_oIP7UlEqnaiW_2z_l7gA1w\", \"direction\": \"OUTBOUND\", \"status\": \"QUEUED\", \"to_number"}, {"title": "Commands", "page": "API reference", "url": "docs/api.html#commands", "lvl": 2, "text": "POST /api/v1/commands Sends a raw command to one device. Body: device_id or device_key , type (default PING ), payload , optional request_id . Requires the operator or admin role. Accepted types: SMS_SEND , SMS_CANCEL , CALL_START , CALL_END , DEVICE_STATUS , DEVICE_COMMAND , PING . The current Android app executes SMS_SEND , CALL_START , CALL_END , PING and DEVICE_STATUS , and reports the others "}, {"title": "Devices", "page": "API reference", "url": "docs/api.html#devices", "lvl": 2, "text": "Endpoint Role Purpose POST /devices admin Create a device. Returns the device and a one-time device_token GET /devices , GET /devices/{id} any List or read devices (login session or bearer token) PATCH /devices/{id} admin Update name , is_enabled , priority (1 to 1000), min_battery_percent (0 to 100) POST /devices/{id}/rotate-token admin Issue a new token; the old one stops working DELETE /devices"}, {"title": "Groups", "page": "API reference", "url": "docs/api.html#groups", "lvl": 2, "text": "POST /api/v1/groups Request (admin) Copy { \"name\": \"Primary\", \"slug\": \"primary\", \"routing_strategy\": \"healthiest\", \"device_ids\": [\"<device-uuid>\"] } slug is 1 to 64 characters of lowercase letters, digits, - and _ , starting with a letter or digit. PATCH /groups/{id} accepts name , description , routing_strategy , is_active and device_ids (which replaces the member list). GET /groups/{id}/preview "}, {"title": "Users and API keys", "page": "API reference", "url": "docs/api.html#users-and-api-keys", "lvl": 2, "text": "Endpoint Purpose POST /users Create a portal user: email , password (8 to 128 characters), full_name , role (default operator ) GET /users , PATCH /users/{id} List users; change role , is_active , full_name or password POST /api-keys Create a key with a name . The full key is returned once GET /api-keys , DELETE /api-keys/{id} List your keys; revoke one All of these require the admin role."}, {"title": "Dashboard data and health", "page": "API reference", "url": "docs/api.html#dashboard-data-and-health", "lvl": 2, "text": "GET /dashboard/stats : device and command counts GET /dashboard/analytics?days=7 (1 to 90): message, call and command totals, volume by day and top devices GET /dashboard/recent-devices , GET /dashboard/recent-commands GET /health (no authentication): {\"status\":\"ok\",\"service\":\"Cellular Gateway\"}"}, {"title": "Roles", "page": "API reference", "url": "docs/api.html#roles", "lvl": 2, "text": "Capability viewer operator admin Read devices, groups, messages, calls, commands, dashboard, analytics yes yes yes Send SMS, start or end calls, create commands no yes yes Create, edit and delete devices and groups; rotate device tokens no no yes Manage webhooks, users and API keys no no yes"}, {"title": "Configuration", "page": "Deploy", "url": "docs/configuration.html", "lvl": 1, "text": "Every server environment variable with its default, plus the Compose and dashboard settings used in production. Server settings # Set these as environment variables, or in server/.env for local development. The production compose files pass the ones listed below into the container. Variable Default Description ENVIRONMENT development production enables startup safety checks, secure cookies and HTTPS-only webhook URLs, and disables /docs SECRET_KEY placeholder JWT signing key. Must be a random string of at l"}, {"title": "Server settings", "page": "Configuration", "url": "docs/configuration.html#server-settings", "lvl": 2, "text": "Set these as environment variables, or in server/.env for local development. The production compose files pass the ones listed below into the container. Variable Default Description ENVIRONMENT development production enables startup safety checks, secure cookies and HTTPS-only webhook URLs, and disables /docs SECRET_KEY placeholder JWT signing key. Must be a random string of at least 32 characters"}, {"title": "Compose variables (production)", "page": "Configuration", "url": "docs/configuration.html#compose-variables-production", "lvl": 2, "text": "Variable Used by Description GATEWAY_DOMAIN both files Public hostname. Sets CORS and the dashboard's API URL, and is the Caddy site address POSTGRES_PASSWORD both files Database password GATEWAY_API_PORT shared-host Loopback port for the API (default 18000 ) GATEWAY_DASHBOARD_PORT shared-host Loopback port for the dashboard (default 13000 ) .env.production.example lists all of them, including the"}, {"title": "Dashboard", "page": "Configuration", "url": "docs/configuration.html#dashboard", "lvl": 2, "text": "NEXT_PUBLIC_API_URL is read at build time and must be the public URL of the API (for example https://gateway.example.com ). The production compose files pass it as a build argument, so rebuild the dashboard image if the domain changes."}, {"title": "Defaults that production rejects", "page": "Configuration", "url": "docs/configuration.html#defaults-that-production-rejects", "lvl": 2, "text": "SECRET_KEY that starts with change-me or is shorter than 32 characters ADMIN_PASSWORD of changeme , admin or password , or shorter than 12 characters ADMIN_EMAIL of admin@example.com A SQLite DATABASE_URL CORS_ORIGINS containing localhost or 127.0.0.1"}, {"title": "Production deployment", "page": "Deploy", "url": "docs/deployment.html", "lvl": 1, "text": "Deploy the gateway on a Linux host with Docker Compose, automatic HTTPS through Caddy, PostgreSQL and Alembic migrations. This guide uses docker-compose.prod.yml : Caddy, the API, the dashboard and PostgreSQL on one host. Caddy is the only service that publishes ports (80 and 443). If the host already runs a reverse proxy, use Behind a reverse proxy instead. Prerequisites # A Linux host with Docker and Docker Compose, with ports 22, 80 and 443 reachable A DNS record (for example gateway.example.com ) pointing at the "}, {"title": "Prerequisites", "page": "Production deployment", "url": "docs/deployment.html#prerequisites", "lvl": 2, "text": "A Linux host with Docker and Docker Compose, with ports 22, 80 and 443 reachable A DNS record (for example gateway.example.com ) pointing at the host. Caddy needs it to obtain a certificate About 2 vCPU and 2 GB RAM is a reasonable starting point for a pilot (an estimate, not a benchmark). Building the dashboard image needs the most memory, so add swap on small hosts"}, {"title": "1. Configure", "page": "Production deployment", "url": "docs/deployment.html#1-configure", "lvl": 2, "text": "bash Copy git clone https://github.com/CLAPTAC/cellular-gateway.git cd cellular-gateway cp .env.production.example .env.production openssl rand -hex 32 # run twice: SECRET_KEY and POSTGRES_PASSWORD Edit .env.production and set: Variable Value GATEWAY_DOMAIN The public hostname, for example gateway.example.com POSTGRES_PASSWORD A random password SECRET_KEY A random string of at least 32 characters "}, {"title": "2. Start", "page": "Production deployment", "url": "docs/deployment.html#2-start", "lvl": 2, "text": "bash Copy docker compose --env-file .env.production -f docker-compose.prod.yml up -d --build docker compose -f docker-compose.prod.yml ps On start the server container applies database migrations ( alembic upgrade head ) and then runs a single uvicorn worker."}, {"title": "3. Verify", "page": "Production deployment", "url": "docs/deployment.html#3-verify", "lvl": 2, "text": "bash Copy curl https://gateway.example.com/health # {\"status\":\"ok\",\"service\":\"Cellular Gateway\"} Open https://gateway.example.com/ and sign in with your administrator account. What Address Dashboard https://<domain>/ API https://<domain>/api/v1 Device WebSocket wss://<domain>/ws/devices Health https://<domain>/health Interactive API docs ( /docs ) are disabled in production."}, {"title": "4. Connect phones", "page": "Production deployment", "url": "docs/deployment.html#4-connect-phones", "lvl": 2, "text": "Install a release build of the Android app and use https://<domain> as the server URL, ideally by scanning the device QR code from the dashboard. Release builds block plain HTTP. See Android app ."}, {"title": "Run exactly one server instance", "page": "Production deployment", "url": "docs/deployment.html#run-exactly-one-server-instance", "lvl": 2, "text": "Device WebSocket sessions and the background workers (offline detection, command queue, webhook delivery) live inside the server process. Do not run more than one replica or use --workers greater than 1. Multi-instance coordination is not implemented."}, {"title": "Updates, backups and logs", "page": "Production deployment", "url": "docs/deployment.html#updates-backups-and-logs", "lvl": 2, "text": "Update Copy git pull docker compose --env-file .env.production -f docker-compose.prod.yml up -d --build Back up the database Copy docker compose -f docker-compose.prod.yml exec postgres \\ pg_dump -U gateway cellular_gateway > backup.sql Logs Copy docker compose -f docker-compose.prod.yml logs -f server Keep backups off the server. Phones reconnect automatically after an update. If you adopt a data"}, {"title": "Overview", "page": "Get started", "url": "docs/", "lvl": 1, "text": "Cellular Gateway is an open-source, self-hosted platform that turns Android phones into managed SMS and voice gateways for your applications. What it does # You run a gateway server and connect one or more Android phones to it. Your applications call the server's REST API to send SMS or place calls, and the server forwards each request to a phone over a persistent WebSocket. The phone uses its own SIM, then reports the result. Inbound SMS and status changes can be delivered to your systems as signed webhooks. Request path Copy Your appl"}, {"title": "What it does", "page": "Overview", "url": "docs/#what-it-does", "lvl": 2, "text": "You run a gateway server and connect one or more Android phones to it. Your applications call the server's REST API to send SMS or place calls, and the server forwards each request to a phone over a persistent WebSocket. The phone uses its own SIM, then reports the result. Inbound SMS and status changes can be delivered to your systems as signed webhooks. Request path Copy Your application --REST-"}, {"title": "Quickstart", "page": "Overview", "url": "docs/#quickstart", "lvl": 3, "text": "Run the server, dashboard and a simulated phone on your machine in minutes."}, {"title": "Deploy to a server", "page": "Overview", "url": "docs/#deploy-to-a-server", "lvl": 3, "text": "Docker Compose with automatic HTTPS, migrations and production safety checks."}, {"title": "API reference", "page": "Overview", "url": "docs/#api-reference", "lvl": 3, "text": "Authentication, messages, calls, commands, devices, groups and more."}, {"title": "Webhooks", "page": "Overview", "url": "docs/#webhooks", "lvl": 3, "text": "Event types, payloads, signature verification and retry behaviour."}, {"title": "Components", "page": "Overview", "url": "docs/#components", "lvl": 2, "text": "Part Role Stack server/ Gateway API, WebSocket hub, queue and webhook workers Python 3.12, FastAPI, SQLAlchemy (async), Alembic, PostgreSQL 16 dashboard/ Management portal for devices, groups, messages, calls, webhooks, users and API keys Next.js 15, React 19, Tailwind CSS android/ Phone app: foreground service, SMS and call control, WebSocket client Kotlin, OkHttp; minSdk 26, targetSdk 35 example"}, {"title": "What happens when you send an SMS", "page": "Overview", "url": "docs/#what-happens-when-you-send-an-sms", "lvl": 2, "text": "Request. Your service calls POST /api/v1/messages with an API key. The gateway validates the request and chooses a device by device key, group strategy, or health score. Command. The gateway stores the message and an SMS_SEND command. If the chosen phone is offline and queueing is allowed, the command waits as QUEUED . Delivery to the phone. The command is pushed over the phone's WebSocket. The ph"}, {"title": "Quickstart", "page": "Get started", "url": "docs/installation.html", "lvl": 1, "text": "Run the gateway locally with SQLite, open the dashboard, and test the full device path with the simulator. No phone required. Requirements # Python 3.12 and Node.js 22 Optional: Docker and Docker Compose, Android Studio (JDK 17) for the phone app 1. Start the server # The server uses SQLite by default, so no configuration is needed for local development. bash Copy cd server python3.12 -m venv .venv source .venv/bin/activate pip install -r requirements.txt uvicorn app.main:app --reload --port 8000 Settings come from envir"}, {"title": "Requirements", "page": "Quickstart", "url": "docs/installation.html#requirements", "lvl": 2, "text": "Python 3.12 and Node.js 22 Optional: Docker and Docker Compose, Android Studio (JDK 17) for the phone app"}, {"title": "1. Start the server", "page": "Quickstart", "url": "docs/installation.html#1-start-the-server", "lvl": 2, "text": "The server uses SQLite by default, so no configuration is needed for local development. bash Copy cd server python3.12 -m venv .venv source .venv/bin/activate pip install -r requirements.txt uvicorn app.main:app --reload --port 8000 Settings come from environment variables or server/.env . The .env in the repository root is only used by Docker Compose."}, {"title": "2. Start the dashboard", "page": "Quickstart", "url": "docs/installation.html#2-start-the-dashboard", "lvl": 2, "text": "bash Copy cd dashboard npm install NEXT_PUBLIC_API_URL=http://localhost:8000 npm run dev Service URL Dashboard http://localhost:3000 API documentation (development only) http://localhost:8000/docs Health check http://localhost:8000/health Sign in with the development administrator admin@example.com / changeme . These defaults are rejected when ENVIRONMENT=production ."}, {"title": "With Docker Compose instead", "page": "Quickstart", "url": "docs/installation.html#with-docker-compose-instead", "lvl": 3, "text": "bash Copy cp .env.example .env docker compose up --build This runs PostgreSQL, the server and the dashboard with live reload. All ports bind to 127.0.0.1 ."}, {"title": "3. Connect a simulated phone", "page": "Quickstart", "url": "docs/installation.html#3-connect-a-simulated-phone", "lvl": 2, "text": "Create a device. In the dashboard open Devices and add one. Copy the one-time device_key and device_token . Run the simulator. bash Copy cd server && source .venv/bin/activate pip install -r ../examples/requirements.txt python ../examples/device_simulator.py \\ --device-key 'dev_...' --device-token 'dvt_...' # options: --base-url (default http://localhost:8000) # --heartbeat-interval (default 10 se"}, {"title": "4. Use a real phone", "page": "Quickstart", "url": "docs/installation.html#4-use-a-real-phone", "lvl": 2, "text": "Build and install the Android app (see Android app ), then scan the device's QR code. For the emulator, use http://10.0.2.2:8000 as the server URL. This works in debug builds only; release builds require HTTPS."}, {"title": "Run the tests", "page": "Quickstart", "url": "docs/installation.html#run-the-tests", "lvl": 2, "text": "bash Copy cd server pip install -r requirements-dev.txt pytest The suite covers production safety checks, login rate limiting, cookie sessions and origin checks, webhook URL protection, device WebSocket authentication, group routing and the examples from these docs. Next Ready for a real server? Continue with Production deployment ."}, {"title": "Multi-device routing", "page": "Integrate", "url": "docs/multi-device.html", "lvl": 1, "text": "Pool phones into groups, choose a device by health, battery or load, queue while offline, and fail SMS over to another phone. Overview # Device groups hold the phones you want to use together, for example one per carrier. Four routing strategies pick a phone for each message or call. If you omit both device and group , the gateway chooses among all enabled devices. queue: true keeps a message or call until a suitable phone is online. Sending to a group queues automatically. A failed SMS sent through a group is retried on"}, {"title": "Overview", "page": "Multi-device routing", "url": "docs/multi-device.html#overview", "lvl": 2, "text": "Device groups hold the phones you want to use together, for example one per carrier. Four routing strategies pick a phone for each message or call. If you omit both device and group , the gateway chooses among all enabled devices. queue: true keeps a message or call until a suitable phone is online. Sending to a group queues automatically. A failed SMS sent through a group is retried on another me"}, {"title": "Create a group", "page": "Multi-device routing", "url": "docs/multi-device.html#create-a-group", "lvl": 2, "text": "Use the dashboard's Groups page, or the API (administrator): bash Copy curl -X POST https://gateway.example.com/api/v1/groups \\ -H \"Authorization: Bearer $TOKEN\" -H \"Content-Type: application/json\" \\ -d '{ \"name\": \"Dialog pool\", \"slug\": \"dialog-pool\", \"routing_strategy\": \"healthiest\", \"device_ids\": [\"DEVICE_UUID_1\", \"DEVICE_UUID_2\"] }'"}, {"title": "Send through a group", "page": "Multi-device routing", "url": "docs/multi-device.html#send-through-a-group", "lvl": 2, "text": "bash Copy curl -X POST https://gateway.example.com/api/v1/messages \\ -H \"X-API-Key: $API_KEY\" -H \"Content-Type: application/json\" \\ -d '{ \"group\": \"dialog-pool\", \"to\": \"+15551234567\", \"message\": \"Routed SMS\", \"queue\": true, \"failover\": true }'"}, {"title": "Strategies", "page": "Multi-device routing", "url": "docs/multi-device.html#strategies", "lvl": 2, "text": "Online phones are always preferred over offline ones. Within that set: Strategy Chooses healthiest (default) The highest health score (see below) round_robin The phone with the fewest in-flight commands, then by score. It balances by current load, not a strict rotation highest_battery The phone with the most battery least_load The fewest in-flight commands plus active calls"}, {"title": "Health score", "page": "Multi-device routing", "url": "docs/multi-device.html#health-score", "lvl": 3, "text": "Each enabled phone gets a score. Higher is better. Component Effect Online (live WebSocket) +1000 Battery above the device's minimum +2 per percentage point (minimum defaults to 15%) In-flight commands (queued, sent, acknowledged) up to +200, minus 20 per command Active calls up to +100, minus 50 per call Priority (1 to 1000, default 100) +(200 minus priority), never below 0. Lower numbers rank hi"}, {"title": "Queueing", "page": "Multi-device routing", "url": "docs/multi-device.html#queueing", "lvl": 2, "text": "With queue: true (or any group send), a command for an offline phone is stored as QUEUED . A background worker checks every 5 seconds and dispatches it when the phone connects. With queue: true on a group send it can also reassign the command to another online member instead of waiting."}, {"title": "Failover", "page": "Multi-device routing", "url": "docs/multi-device.html#failover", "lvl": 2, "text": "Applies to SMS only , and only when the message was sent to a group . After a FAILED result the gateway retries on another group member, excluding the phone that failed. There are at most 3 attempts in total. Set failover: false to disable it. Calls are never retried automatically."}, {"title": "Operations and limits", "page": "Operate", "url": "docs/operations.html", "lvl": 1, "text": "Logs, health checks, migrations, backups, troubleshooting, and the current limitations of the gateway. Day-to-day # Task How Health check GET /health returns {\"status\":\"ok\",\"service\":\"Cellular Gateway\"} Logs docker compose -f docker-compose.prod.yml logs -f server . Failures in the background workers (offline detection, command queue, webhook delivery) are logged Migrations Applied automatically on container start. Create one with alembic revision --autogenerate -m \"description\" in server/ Backup d"}, {"title": "Day-to-day", "page": "Operations and limits", "url": "docs/operations.html#day-to-day", "lvl": 2, "text": "Task How Health check GET /health returns {\"status\":\"ok\",\"service\":\"Cellular Gateway\"} Logs docker compose -f docker-compose.prod.yml logs -f server . Failures in the background workers (offline detection, command queue, webhook delivery) are logged Migrations Applied automatically on container start. Create one with alembic revision --autogenerate -m \"description\" in server/ Backup docker compose"}, {"title": "Troubleshooting", "page": "Operations and limits", "url": "docs/operations.html#troubleshooting", "lvl": 2, "text": "Symptom Likely cause Server exits at startup with \"Refusing to start with insecure configuration\" Production safety checks. The message lists each setting to fix 409 No online devices available The target phone is offline and neither queue nor group was used Device flips between ONLINE and OFFLINE A proxy timeout under about 30 seconds, battery optimization killing the app, or an unstable mobile c"}, {"title": "Known limitations", "page": "Operations and limits", "url": "docs/operations.html#known-limitations", "lvl": 2, "text": "Single server instance. Device sockets and background workers are in-process. Running more than one replica is unsupported and would need shared state such as Redis. Real-phone validation. SMS and call behaviour has been tested with the simulator and automated tests, not yet on physical phones with SIM cards. Placeholder signal data. The Android app currently reports a fixed signal strength and ne"}, {"title": "Roadmap", "page": "Operations and limits", "url": "docs/operations.html#roadmap", "lvl": 2, "text": "Phase Scope Status 1 Core platform: devices, commands, WebSocket, dashboard Done 2 Real SMS send and receive Done 3 Voice call control Done 4 Multi-device routing and failover Done 5 Webhooks, role-based access, analytics Done Next Multi-instance support, carrier delivery reports, scheduled messages and templates, USSD, SIM management, metrics export Planned"}, {"title": "QR provisioning", "page": "Devices", "url": "docs/qr-provisioning.html", "lvl": 1, "text": "Connect a phone by scanning a QR code instead of typing a server URL and long credentials. When you create a device, or rotate its token, the dashboard shows a QR code. Scanning it in the Android app fills in the server URL and credentials and connects automatically. Payload # json Copy { \"v\": 1, \"server_url\": \"https://gateway.example.com\", \"device_key\": \"dev_...\", \"device_token\": \"dvt_...\" } The QR code contains the device token, so treat it like a password. It is shown once, at creati"}, {"title": "Payload", "page": "QR provisioning", "url": "docs/qr-provisioning.html#payload", "lvl": 2, "text": "json Copy { \"v\": 1, \"server_url\": \"https://gateway.example.com\", \"device_key\": \"dev_...\", \"device_token\": \"dvt_...\" } The QR code contains the device token, so treat it like a password. It is shown once, at creation or rotation."}, {"title": "Flow", "page": "QR provisioning", "url": "docs/qr-provisioning.html#flow", "lvl": 2, "text": "Create the device. Dashboard, then Devices , then add a device. Set the server URL for the phone. It must be reachable from the phone. For local testing use your computer's LAN address, not localhost . In production use your public https:// URL. Scan. In the phone app choose Scan QR . It fills the fields and connects."}, {"title": "Show the QR code again", "page": "QR provisioning", "url": "docs/qr-provisioning.html#show-the-qr-code-again", "lvl": 2, "text": "Open the device and choose Show QR again . This issues a new token , so the previous token stops working and the phone must scan again. Why not type credentials Device tokens are long random strings. Scanning avoids typing mistakes and keeps the token off the clipboard."}, {"title": "Security", "page": "Operate", "url": "docs/security.html", "lvl": 1, "text": "How the gateway protects credentials, browser sessions, webhooks and the network edge, and what you still need to do. What the gateway enforces # Area Behaviour Startup With ENVIRONMENT=production the server refuses to start on default or weak secrets, SQLite, or localhost CORS Transport TLS terminates at Caddy or your reverse proxy. Release builds of the Android app block plain HTTP Browser sessions An httpOnly cookie, so page scripts cannot read the token, plus SameSite=Strict and an Origin check on cookie-auth"}, {"title": "What the gateway enforces", "page": "Security", "url": "docs/security.html#what-the-gateway-enforces", "lvl": 2, "text": "Area Behaviour Startup With ENVIRONMENT=production the server refuses to start on default or weak secrets, SQLite, or localhost CORS Transport TLS terminates at Caddy or your reverse proxy. Release builds of the Android app block plain HTTP Browser sessions An httpOnly cookie, so page scripts cannot read the token, plus SameSite=Strict and an Origin check on cookie-authenticated writes Secrets at "}, {"title": "Roles", "page": "Security", "url": "docs/security.html#roles", "lvl": 2, "text": "Role Can do viewer Read devices, groups, messages, calls, commands, dashboard and analytics operator Everything a viewer can, plus send SMS, start or end calls and create commands admin Everything, including devices, groups, webhooks, users and API keys API keys act with the permissions of the administrator who created them and are accepted only on the messages , calls and commands endpoints. Crea"}, {"title": "Your checklist", "page": "Security", "url": "docs/security.html#your-checklist", "lvl": 2, "text": "Use long random values for SECRET_KEY and POSTGRES_PASSWORD , and a strong administrator password. Expose only ports 80 and 443. Keep SSH restricted, and keep the host patched. Verify webhook signatures on your receiver and deduplicate on the delivery id . Rotate a device token if a phone or QR code is lost, and disable devices you no longer use. Back up the database and store backups off the serv"}, {"title": "Behind a reverse proxy", "page": "Deploy", "url": "docs/shared-host.html", "lvl": 1, "text": "Run the gateway on a host that already has nginx, Apache, Traefik or Caddy. The stack binds to loopback and your proxy handles TLS. Use docker-compose.shared.yml when the host already serves other sites and ports 80 and 443 are taken. It starts PostgreSQL, the API and the dashboard, without Caddy. The API listens on 127.0.0.1:18000 and the dashboard on 127.0.0.1:13000 (change them with GATEWAY_API_PORT and GATEWAY_DASHBOARD_PORT ). PostgreSQL is not published. Start the stack # bash Copy cp .env.production.example .env.product"}, {"title": "Start the stack", "page": "Behind a reverse proxy", "url": "docs/shared-host.html#start-the-stack", "lvl": 2, "text": "bash Copy cp .env.production.example .env.production # GATEWAY_DOMAIN = your public hostname docker compose --env-file .env.production -f docker-compose.shared.yml up -d --build curl -s http://127.0.0.1:18000/health"}, {"title": "Routing rules", "page": "Behind a reverse proxy", "url": "docs/shared-host.html#routing-rules", "lvl": 2, "text": "Add a host for GATEWAY_DOMAIN in your proxy with these rules, whichever proxy you use: Path Upstream /api/* , /health 127.0.0.1:18000 /ws/* 127.0.0.1:18000 , with WebSocket upgrade everything else 127.0.0.1:13000 The proxy must serve HTTPS (release builds of the Android app refuse http:// ) and send X-Forwarded-For and X-Forwarded-Proto . Phones send a heartbeat every 10 seconds, so a read timeout"}, {"title": "Proxy configuration", "page": "Behind a reverse proxy", "url": "docs/shared-host.html#proxy-configuration", "lvl": 2, "text": "nginx Caddy Apache Traefik nginx Copy map $http_upgrade $connection_upgrade { default upgrade; '' close; } server { listen 443 ssl http2; server_name gateway.example.com; ssl_certificate /etc/letsencrypt/live/gateway.example.com/fullchain.pem; ssl_certificate_key /etc/letsencrypt/live/gateway.example.com/privkey.pem; proxy_set_header Host $host; proxy_set_header X-Forwarded-For $remote_addr; proxy"}, {"title": "Check it works", "page": "Behind a reverse proxy", "url": "docs/shared-host.html#check-it-works", "lvl": 2, "text": "curl https://gateway.example.com/health returns {\"status\":\"ok\",\"service\":\"Cellular Gateway\"} . Sign in at https://gateway.example.com/ . Connect a device and confirm it stays ONLINE for more than a minute. If it flips between ONLINE and OFFLINE , check for a proxy timeout under about 30 seconds, then phone battery optimization and network stability."}, {"title": "SMS", "page": "Integrate", "url": "docs/sms.html", "lvl": 1, "text": "Send outbound SMS through a phone's SIM, receive inbound SMS, and track message status and failures. What works # POST /api/v1/messages creates an outbound SMS command and a message record. An online phone sends the text with Android's SmsManager , splitting long messages into parts. The message moves to SENT or FAILED , and SMS_SENT or SMS_FAILED webhooks fire. Inbound SMS on the phone are reported to the server and stored as INBOUND messages, and an SMS_RECEIVED webhook fires. The dashboard's M"}, {"title": "What works", "page": "SMS", "url": "docs/sms.html#what-works", "lvl": 2, "text": "POST /api/v1/messages creates an outbound SMS command and a message record. An online phone sends the text with Android's SmsManager , splitting long messages into parts. The message moves to SENT or FAILED , and SMS_SENT or SMS_FAILED webhooks fire. Inbound SMS on the phone are reported to the server and stored as INBOUND messages, and an SMS_RECEIVED webhook fires. The dashboard's Messages page "}, {"title": "Phone setup", "page": "SMS", "url": "docs/sms.html#phone-setup", "lvl": 2, "text": "Install and connect the Android app and scan the device QR code. Allow SMS permissions when prompted (send, receive and read SMS). Keep the app running. Disable battery optimization for it, and on some manufacturers (Xiaomi and similar) also allow autostart and background activity."}, {"title": "Send a message", "page": "SMS", "url": "docs/sms.html#send-a-message", "lvl": 2, "text": "curl Python curl Copy curl -X POST https://gateway.example.com/api/v1/messages \\ -H \"X-API-Key: $API_KEY\" \\ -H \"Content-Type: application/json\" \\ -d '{ \"device\": \"dev_YOUR_DEVICE_KEY\", \"to\": \"+15551234567\", \"message\": \"Hello from Cellular Gateway\" }' Python Copy import os, requests r = requests.post( \"https://gateway.example.com/api/v1/messages\", headers={\"X-API-Key\": os.environ[\"GATEWAY_API_KEY\"]"}, {"title": "Track the result", "page": "SMS", "url": "docs/sms.html#track-the-result", "lvl": 2, "text": "bash Copy curl https://gateway.example.com/api/v1/messages/$MESSAGE_ID -H \"X-API-Key: $API_KEY\" Status Meaning QUEUED Waiting for a phone to come online SENDING Handed to a phone SENT The phone's radio accepted the message DELIVERED Delivery confirmed (best effort, not normalized across carriers) FAILED The phone reported an error. Check error_message RECEIVED An inbound message"}, {"title": "Receive messages", "page": "SMS", "url": "docs/sms.html#receive-messages", "lvl": 2, "text": "Inbound SMS arrive as SMS_RECEIVED webhooks (body truncated to 200 characters) and are stored in full. Read them with GET /api/v1/messages and look for direction: \"INBOUND\" ."}, {"title": "Notes", "page": "SMS", "url": "docs/sms.html#notes", "lvl": 2, "text": "Without queue or a group , an offline target device returns 409 . Carrier SMS charges and Android's sending limits apply. Android may throttle or prompt on bursts of outgoing SMS. Delivery receipts from carriers are not fully supported. Treat SENT as accepted for sending, not delivered. There is no idempotency key. If your request times out and you retry, the SMS may be sent twice, so deduplicate "}, {"title": "Voice", "page": "Integrate", "url": "docs/voice.html", "lvl": 1, "text": "Start and end outbound calls through a phone and follow call state from dialing to ended. What works # POST /api/v1/calls starts an outbound call on an online phone. POST /api/v1/calls/{id}/end ends an active call (Android 9 or newer). Call state changes ( DIALING , RINGING , ACTIVE , ENDED and others) are reported over the WebSocket, stored, and sent as CALL_STATE webhooks. Call history is available through the API and the dashboard's Calls page. Signalling only The gateway dials the "}, {"title": "What works", "page": "Voice", "url": "docs/voice.html#what-works", "lvl": 2, "text": "POST /api/v1/calls starts an outbound call on an online phone. POST /api/v1/calls/{id}/end ends an active call (Android 9 or newer). Call state changes ( DIALING , RINGING , ACTIVE , ENDED and others) are reported over the WebSocket, stored, and sent as CALL_STATE webhooks. Call history is available through the API and the dashboard's Calls page. Signalling only The gateway dials the number throug"}, {"title": "Phone setup", "page": "Voice", "url": "docs/voice.html#phone-setup", "lvl": 2, "text": "Allow these permissions in the Android app: call phone ( CALL_PHONE ), read phone state ( READ_PHONE_STATE ) and answer phone calls ( ANSWER_PHONE_CALLS , needed to hang up remotely). Keep the app connected and the device online."}, {"title": "Examples", "page": "Voice", "url": "docs/voice.html#examples", "lvl": 2, "text": "bash Copy # Start curl -X POST https://gateway.example.com/api/v1/calls \\ -H \"X-API-Key: $API_KEY\" -H \"Content-Type: application/json\" \\ -d '{\"device\": \"dev_...\", \"to\": \"+15551234567\"}' # End curl -X POST https://gateway.example.com/api/v1/calls/$CALL_ID/end \\ -H \"X-API-Key: $API_KEY\" # List curl https://gateway.example.com/api/v1/calls -H \"X-API-Key: $API_KEY\" Calls accept device , group , strate"}, {"title": "Call statuses", "page": "Voice", "url": "docs/voice.html#call-statuses", "lvl": 2, "text": "Status Meaning QUEUED Waiting for a phone to come online DIALING The phone has started the call RINGING Ringing ACTIVE Connected HOLDING On hold ENDED Finished. duration_seconds is measured from answer time, or from dialing if the call was never answered FAILED , CANCELLED The call did not complete"}, {"title": "Notes", "page": "Voice", "url": "docs/voice.html#notes", "lvl": 2, "text": "Without queue or a group , an offline target device returns 409 . Carrier call charges apply. Some manufacturers restrict background call control. Keep the app unlocked or in the foreground if calls are unreliable. Ending a call needs Android 9 or newer; older versions report UNSUPPORTED ."}, {"title": "Webhooks", "page": "Integrate", "url": "docs/webhooks.html", "lvl": 1, "text": "Receive signed events for inbound SMS, delivery results, call state and device status, with retries and a delivery history. Create an endpoint # Administrators create endpoints in the dashboard ( Webhooks ) or with the API. POST /api/v1/webhooks Request Copy { \"name\": \"crm\", \"url\": \"https://example.org/hooks/gateway\", \"events\": [\"SMS_RECEIVED\", \"SMS_FAILED\"] } events defaults to all event types, and \"*\" is accepted. The response contains the signing secret ( whsec_... ) exactly once; rotate it with POST /webhooks/{id}/"}, {"title": "Create an endpoint", "page": "Webhooks", "url": "docs/webhooks.html#create-an-endpoint", "lvl": 2, "text": "Administrators create endpoints in the dashboard ( Webhooks ) or with the API. POST /api/v1/webhooks Request Copy { \"name\": \"crm\", \"url\": \"https://example.org/hooks/gateway\", \"events\": [\"SMS_RECEIVED\", \"SMS_FAILED\"] } events defaults to all event types, and \"*\" is accepted. The response contains the signing secret ( whsec_... ) exactly once; rotate it with POST /webhooks/{id}/rotate-secret . List "}, {"title": "Events", "page": "Webhooks", "url": "docs/webhooks.html#events", "lvl": 2, "text": "Event Emitted when data fields SMS_RECEIVED A phone receives an SMS from , body (truncated to 200 characters), message_id SMS_SENT An outbound SMS command completes request_id , result SMS_FAILED An outbound SMS command fails request_id , error CALL_STATE A call changes state state , status , call_id , number DEVICE_ONLINE , DEVICE_OFFLINE A phone connects or disconnects connection_id COMMAND_COMP"}, {"title": "Delivery format", "page": "Webhooks", "url": "docs/webhooks.html#delivery-format", "lvl": 2, "text": "POST to your URL Copy { \"id\": \"<delivery uuid>\", \"type\": \"SMS_RECEIVED\", \"created_at\": \"2026-01-01T12:00:00+00:00\", \"data\": { \"from\": \"+15551234567\", \"body\": \"Hello\", \"message_id\": \"...\", \"device_id\": \"...\", \"message\": \"Inbound SMS from +15551234567\" } } Header Value Content-Type application/json X-CG-Event The event type X-CG-Delivery Delivery id, identical to id in the body X-CG-Signature sha256"}, {"title": "Verify the signature", "page": "Webhooks", "url": "docs/webhooks.html#verify-the-signature", "lvl": 2, "text": "Compute the HMAC-SHA256 of the raw request body with the endpoint secret and compare it in constant time. Do not re-serialize the JSON before checking. Python Node Python Copy import hashlib, hmac def is_valid(secret: str, raw_body: bytes, header: str) -> bool: expected = \"sha256=\" + hmac.new(secret.encode(), raw_body, hashlib.sha256).hexdigest() return hmac.compare_digest(expected, header) Node C"}, {"title": "Delivery rules", "page": "Webhooks", "url": "docs/webhooks.html#delivery-rules", "lvl": 2, "text": "A 2xx response within 10 seconds counts as success. Anything else is retried. There are up to 5 attempts in total, spaced 30 seconds, 2 minutes, 10 minutes and 30 minutes apart (about 42 minutes overall). After that the delivery is marked FAILED . The id stays the same across retries. Deduplicate on it, because a delivery can arrive more than once. Order is not guaranteed. URLs must use https in p"}, {"title": "WebSocket protocol", "page": "Devices", "url": "docs/websocket.html", "lvl": 1, "text": "The device channel: authentication, message types, command acknowledgements, heartbeats and close codes. Phones keep one WebSocket open to the server. The server pushes commands, and the phone reports acknowledgements, heartbeats, inbound SMS and call state. Every message is a JSON object with a type . Connect # Register. The phone calls POST /api/v1/devices/register with its key and token. Open the socket at wss://<host>/ws/devices . Authenticate. The server replies with ready , or closes with an er"}, {"title": "Connect", "page": "WebSocket protocol", "url": "docs/websocket.html#connect", "lvl": 2, "text": "Register. The phone calls POST /api/v1/devices/register with its key and token. Open the socket at wss://<host>/ws/devices . Authenticate. The server replies with ready , or closes with an error code. Handshake headers Copy GET /ws/devices X-Device-Key: dev_... X-Device-Token: dvt_... Headers keep credentials out of proxy and access logs. The query form /ws/devices?device_key=...&device_token=... "}, {"title": "Server to phone", "page": "WebSocket protocol", "url": "docs/websocket.html#server-to-phone", "lvl": 2, "text": "ready Copy { \"type\": \"ready\", \"connection_id\": \"...\", \"device_id\": \"...\", \"timestamp\": \"2026-01-01T12:00:00+00:00\" } command Copy { \"type\": \"command\", \"command\": { \"type\": \"SMS_SEND\", \"request_id\": \"req_123\", \"device_id\": \"...\", \"payload\": { \"to\": \"+15551234567\", \"message\": \"Hello\" } } } Command types in the schema: SMS_SEND , SMS_CANCEL , CALL_START , CALL_END , DEVICE_STATUS , DEVICE_COMMAND , P"}, {"title": "Phone to server", "page": "WebSocket protocol", "url": "docs/websocket.html#phone-to-server", "lvl": 2, "text": "heartbeat Copy { \"type\": \"heartbeat\", \"payload\": { \"battery\": 87, \"signal_strength\": 78, \"network\": \"4G\", \"manufacturer\": \"Google\", \"model\": \"Pixel\", \"android_version\": \"14\", \"app_version\": \"0.3.0\" } } battery and signal_strength are integers from 0 to 100. The Android app sends a heartbeat every 10 seconds. command_ack Copy { \"type\": \"command_ack\", \"payload\": { \"request_id\": \"req_123\", \"status\": "}, {"title": "Close codes", "page": "WebSocket protocol", "url": "docs/websocket.html#close-codes", "lvl": 2, "text": "Code Meaning 4401 Unauthorized: unknown device or wrong token 4403 Device disabled 4404 Device not found 4000 Replaced by a newer connection from the same device 4429 Too many failed attempts from this IP 1011 Server error"}, {"title": "Presence and offline detection", "page": "WebSocket protocol", "url": "docs/websocket.html#presence-and-offline-detection", "lvl": 2, "text": "A device is ONLINE while its socket is open. If a device has no live socket and its last heartbeat is older than DEVICE_HEARTBEAT_TIMEOUT_SECONDS (default 45), a background check marks it OFFLINE . Queued commands are dispatched when it reconnects."}];
